static constexpr int kNumFontAtlases = 7;

/* Find the best-matching font atlas for the requested size */
static inline const FontAtlas* font_atlas_find(int target_size) {
    if (kNumFontAtlases == 0) return nullptr;
    const FontAtlas* best = font_atlases[0];
    int best_diff = target_size > best->size ? target_size - best->size : best->size - target_size;
    for (int i = 1; i < kNumFontAtlases; i++) {
        int diff = target_size > font_atlases[i]->size ? target_size - font_atlases[i]->size : font_atlases[i]->size - target_size;
        if (diff < best_diff) { best = font_atlases[i]; best_diff = diff; }
    }
    return best;
}

