static constexpr int kNumFontAtlasesBold = 7;

/* Find the best-matching bold font atlas for the requested size */
static inline const FontAtlas* font_atlas_find_bold(int target_size) {
    if (kNumFontAtlasesBold == 0) return nullptr;
    const FontAtlas* best = font_atlases_bold[0];
    int best_diff = target_size > best->size ? target_size - best->size : best->size - target_size;
    for (int i = 1; i < kNumFontAtlasesBold; i++) {
        int diff = target_size > font_atlases_bold[i]->size ? target_size - font_atlases_bold[i]->size : font_atlases_bold[i]->size - target_size;
        if (diff < best_diff) { best = font_atlases_bold[i]; best_diff = diff; }
    }
    return best;
}

