static constexpr int kNumFontAtlasesCommp = 5;

/* Find the best-matching COMMP atlas for the requested size */
static inline const FontAtlas* font_atlas_find_commp(int target_size) {
    if (kNumFontAtlasesCommp == 0) return nullptr;
    const FontAtlas* best = font_atlases_commp[0];
    int best_diff = target_size > best->size ? target_size - best->size : best->size - target_size;
    for (int i = 1; i < kNumFontAtlasesCommp; i++) {
        int diff = target_size > font_atlases_commp[i]->size ? target_size - font_atlases_commp[i]->size : font_atlases_commp[i]->size - target_size;
        if (diff < best_diff) { best = font_atlases_commp[i]; best_diff = diff; }
    }
    return best;
}

/* Case-insensitive family match: 'commp' / 'common pixel' -> the
 * COMMP pixel family; anything else -> the default sans-serif family. */
static inline bool font_family_is_commp(const char* family) {
    if (!family) return false;
    auto lc = [](char c) -> char {
        return (c >= 'A' && c <= 'Z') ? (char)(c - 'A' + 'a') : c; };
    auto ieq = [&](const char* s, const char* t) -> bool {
        while (*s && *t) { if (lc(*s) != lc(*t)) return false; s++; t++; }
        return *s == *t; };
    return ieq(family, "commp") || ieq(family, "common pixel");
}

/* Family + size finder (regular weight of the named family). */
static inline const FontAtlas* font_atlas_find_family(const char* family, int target_size) {
    if (font_family_is_commp(family)) {
        const FontAtlas* a = font_atlas_find_commp(target_size);
        if (a) return a;   /* fall through to sans if COMMP absent */
    }
    return font_atlas_find(target_size);
}

/* Family + weight + size selector (the canvas seam): COMMP is a
 * single-weight pixel family (bold maps to the same face); the
 * default family honours the bold weight. */
static inline const FontAtlas* font_atlas_find_styled(bool commp, bool bold, int target_size) {
    if (commp) { const FontAtlas* a = font_atlas_find_commp(target_size); if (a) return a; }
    return bold ? font_atlas_find_bold(target_size) : font_atlas_find(target_size);
}

/* Get glyph for a character from an atlas */
static inline const FontGlyph* font_atlas_glyph(const FontAtlas* atlas, int char_code) {
    if (char_code < 32 || char_code > 126) return nullptr;
    return &atlas->glyphs[char_code - 32];
}

#endif /* FONT_ATLAS_H */
